export type ConsentChannel="voice"|"whatsapp"|"sms"|"email";
const CONSENT_COLUMNS:Record<ConsentChannel,string>={voice:"voice_allowed",whatsapp:"whatsapp_allowed",sms:"sms_allowed",email:"email_allowed"};
/**
 * Customer-owned central channel consent. The ONLY legitimate writer of a per-channel allow/deny besides recordGlobalOptOut.
 * Rules: the subject writes for themself only (the route enforces the platform-session subject); a missing row never defaults
 * to allowed and is created with every channel NULL except the one declared; a declared `false` is a refusal, not a deletion;
 * a global opt-out is never lifted here (it stays 1 until the opt-out owner lifts it); `source` names the app surface and
 * `updatedBy` the acting subject so the row is attributable. Returns the exact persisted row.
 */
export async function recordCustomerChannelConsent(db:Db,input:{customerId:string;channel:ConsentChannel;allowed:boolean;source:string;updatedBy:string;asOf?:number}){
 await ensureCommunicationGovernance(db);
 const customerId=String(input.customerId||"").trim(),source=String(input.source||"").trim(),updatedBy=String(input.updatedBy||"").trim();
 if(!customerId||!source||!updatedBy)throw new Response("Customer, source and acting subject are required",{status:400});
 const column=CONSENT_COLUMNS[input.channel];if(!column)throw new Response("Unsupported consent channel",{status:400});
 if(typeof input.allowed!=="boolean")throw new Response("Consent must be an explicit boolean",{status:400});
 const now=input.asOf??Date.now(),value=input.allowed?1:0;
 await db.prepare(`INSERT INTO communication_consent(customer_id,global_opt_out,whatsapp_allowed,email_allowed,voice_allowed,sms_allowed,source,updated_by,updated_at) VALUES (?,0,NULL,NULL,NULL,NULL,?,?,?) ON CONFLICT(customer_id) DO UPDATE SET source=excluded.source,updated_by=excluded.updated_by,updated_at=excluded.updated_at`).bind(customerId,source,updatedBy,now).run();
 await db.prepare(`UPDATE communication_consent SET ${column}=? WHERE customer_id=?`).bind(value,customerId).run();
 const row=await db.prepare("SELECT customer_id,global_opt_out,whatsapp_allowed,email_allowed,voice_allowed,sms_allowed,source,updated_by,updated_at FROM communication_consent WHERE customer_id=?").bind(customerId).first<Row>();
 return{customerId,channel:input.channel,allowed:input.allowed,globalOptOut:Number(row?.global_opt_out||0)===1,effectiveAllowed:Number(row?.global_opt_out||0)!==1&&Number(row?.[column])===1,source,updatedBy,updatedAt:now};
}
